head.script:
scwin.fn_openPopup = function(a) {
	requires("uiplugin.popup");
	var options = {
		id: "popup2",
		type: "browserPopup",
		width: 300 + "px",
		height: 300 + "px",
		top: 100 + "px",
		left: 100 + "px",
		modal: true
	};
	$p.openPopup("", options);
};

scwin.trigger3_onclick = function(e) {
	scwin.fn_openPopup("bbb");
};

// Jira 재현방법의 useModalStack: true 조건
scwin.trigger4_onclick = function(e) {
	requires("uiplugin.popup");
	$p.openPopup("", {
		id: "popup3",
		type: "browserPopup",
		width: 300 + "px",
		height: 300 + "px",
		top: 100 + "px",
		left: 100 + "px",
		modal: true,
		useModalStack: true
	});
};
